import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_a_nonconversion():
    assert conversion_rate([{"converted": None}, {"converted": True}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_duplicate_id_keeps_last_input_record_not_latest_day():
    old = {"id": "b", "day": 4, "converted": True}
    replacement = {"id": "b", "day": 1, "converted": False}
    a = {"id": "a", "day": 1, "converted": True}
    c = {"id": "c", "day": 0, "converted": None}
    assert dedupe_sessions([old, a, replacement, c]) == [c, a, replacement]


def test_parse_ignores_whitespace_and_comments():
    events = parse_session_log(["", " \t", "  # comment", " a , 3 , 0 ", " b , 2 , "])
    assert events == [
        {"id": "a", "day": 3, "converted": False},
        {"id": "b", "day": 2, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,3", "x,3,1,extra", "x,day,1"])
def test_parse_error_reports_position_including_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["a,1,1", " # comment", "", bad_line])


def test_daily_counts_fill_gaps_and_ignore_outside_days():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,4,1"])
    assert daily_conversion_counts(events, 1, 3) == [0, 2, 0]
    assert daily_conversion_counts(events, 3, 2) == []


@pytest.mark.parametrize("days,expected", [(0, 0), (2, 5), (7, 6)])
def test_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_campaign_summary_uses_session_weighting_and_calendar_days():
    groups = {"a": parse_session_log(["a,1,1"]), "b": parse_session_log(["b,4,0", "c,1,"]), "c": []}
    assert campaign_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary({"a": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert pooled_conversion_rate({}) == 0.0


def test_group_ranking_and_rate_order():
    groups = {"z": [{"converted": True}], "a": [{"converted": True}], "x": [], "b": [{"converted": False}]}
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("x", None), ("z", 1.0)]


@pytest.mark.parametrize("counts,expected", [([], 0), ([0, -1], 0), ([1, 0, 2, 3, -1, 1], 2)])
def test_streak_counts_only_consecutive_positive_days(counts, expected):
    assert longest_conversion_streak(counts) == expected
